import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MAX_DOTS = 6
private const val DOMINO_TYPES = 21

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    val edges = ArrayList<Pair<Int, Int>>(m)
    repeat(m) {
        st = StringTokenizer(br.readLine())
        val a = st.nextToken().toInt() - 1
        val b = st.nextToken().toInt() - 1
        edges.add(Pair(a, b))
    }

    // Precompute all domino types (a,b) with 1<=a<=b<=6
    val domA = IntArray(DOMINO_TYPES)
    val domB = IntArray(DOMINO_TYPES)
    var idx = 0
    for (a in 1..MAX_DOTS) {
        for (b in a..MAX_DOTS) {
            domA[idx] = a
            domB[idx] = b
            idx++
        }
    }

    val maxMask = 1 shl MAX_DOTS
    val bestForMask = IntArray(maxMask) { -1 }

    fun dfsDomino(pos: Int, mask: Int, count: Int) {
        if (pos == DOMINO_TYPES) {
            if (count > bestForMask[mask]) bestForMask[mask] = count
            return
        }
        // skip this domino
        dfsDomino(pos + 1, mask, count)

        val a = domA[pos] - 1
        val b = domB[pos] - 1
        val newMask = mask or (1 shl a) or (1 shl b)
        dfsDomino(pos + 1, newMask, count + 1)
    }

    dfsDomino(0, 0, 0)

    // DP over subsets to get maximum number of dominoes for any subset
    for (mask in 0 until maxMask) {
        var sub = mask
        while (sub > 0) {
            val other = mask xor sub
            if (bestForMask[sub] >= 0 && bestForMask[other] >= 0) {
                val v = bestForMask[sub] + bestForMask[other]
                if (v > bestForMask[mask]) bestForMask[mask] = v
            }
            sub = (sub - 1) and mask
        }
    }

    val adjMask = IntArray(n)
    for ((u, v) in edges) {
        adjMask[u] = adjMask[u] or (1 shl v)
        adjMask[v] = adjMask[v] or (1 shl u)
    }

    var answer = 0
    val totalMasks = 1 shl n

    for (mask in 0 until totalMasks) {
        // Check if mask is a union of cliques
        var ok = true
        var remaining = mask
        while (remaining != 0 && ok) {
            val v = Integer.numberOfTrailingZeros(remaining)
            val clique = remaining and adjMask[v] and mask
            val comp = clique or (1 shl v)
            // verify comp is a clique
            var sub = comp
            while (sub != 0 && ok) {
                val u = Integer.numberOfTrailingZeros(sub)
                val needed = (comp xor (1 shl u))
                if ((adjMask[u] and needed) != needed) ok = false
                sub = sub and (sub - 1)
            }
            remaining = remaining and comp.inv()
        }
        if (!ok) continue

        // For this mask, compute sum of bestForMask over connected components
        var total = 0
        var rem = mask
        while (rem != 0) {
            val v = Integer.numberOfTrailingZeros(rem)
            // BFS/DFS to get connected component
            var comp = 0
            val stack = IntArray(n)
            var sp = 0
            stack[sp++] = v
            comp = comp or (1 shl v)
            rem = rem and (1 shl v).inv()
            while (sp > 0) {
                val cur = stack[--sp]
                val neighbors = adjMask[cur] and mask
                var tmp = neighbors
                while (tmp != 0) {
                    val u = Integer.numberOfTrailingZeros(tmp)
                    val bit = 1 shl u
                    if ((comp and bit) == 0) {
                        comp = comp or bit
                        rem = rem and bit.inv()
                        stack[sp++] = u
                    }
                    tmp = tmp and (tmp - 1)
                }
            }
            val size = Integer.bitCount(comp)
            if (size > 0) {
                val dotsMask = (1 shl size) - 1
                total += bestForMask[dotsMask]
            }
        }
        if (total > answer) answer = total
    }

    println(answer)
}

