private const val DOMINO_TYPES = 21

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    val edges = ArrayList<Pair<Int, Int>>(m)
    repeat(m) {
        st = StringTokenizer(br.readLine())
        val a = st.nextToken().toInt() - 1
        val b = st.nextToken().toInt() - 1
        edges.add(Pair(a, b))
    }

    // Precompute all domino types (a,b) with 1<=a<=b<=6
    val domA = IntArray(DOMINO_TYPES)
    val domB = IntArray(DOMINO_TYPES)
    var idx = 0
    for (a in 1..MAX_DOTS) {
        for (b in a..MAX_DOTS) {
            domA[idx] = a
            domB[idx] = b
            idx++
        }
    }

    // Precompute all possible assignments of dot counts to vertices
    // Each vertex gets a value in [1..6]
    val totalAssignments = IntArray(n)
    val maxMask = IntArray(1) // dummy

    var best = 0

    fun dfsAssign(v: Int) {
        if (v == n) {
            // For this assignment, build list of possible domino placements
            val possibleEdges = ArrayList<Int>() // store edge index
            val edgeDomMask = IntArray(m) // bitmask of domino types that can be used on this edge

            for (e in 0 until m) {
                val (u, w) = edges[e]
                val cu = totalAssignments[u]
                val cw = totalAssignments[w]
                var mask = 0
                for (d in 0 until DOMINO_TYPES) {
                    val a = domA[d]
                    val b = domB[d]
                    // Check if domino (a,b) can be oriented to match cu at u and cw at w
                    if ((a == cu && b == cw) || (a == cw && b == cu)) {
                        mask = mask or (1 shl d)
                    }
                }
                edgeDomMask[e] = mask
                if (mask != 0) possibleEdges.add(e)
            }

            val k = possibleEdges.size
            if (k == 0) return

            // Backtracking over edges to choose a maximum matching with unique domino types
            var localBest = 0

            fun backtrack(pos: Int, usedDominoMask: Int, placed: Int) {
                if (pos == k) {
                    if (placed > localBest) localBest = placed
                    return
                }
                // Upper bound pruning
                if (placed + (k - pos) <= localBest) return

                val eIdx = possibleEdges[pos]
                val options = edgeDomMask[eIdx] and usedDominoMask.inv()
                // Option 1: skip this edge
                backtrack(pos + 1, usedDominoMask, placed)

                // Option 2: try each available domino type
                var opt = options
                while (opt != 0) {
                    val d = opt and -opt
                    val dIdx = Integer.numberOfTrailingZeros(d)
                    backtrack(pos + 1, usedDominoMask or (1 shl dIdx), placed + 1)
                    opt -= d
                }
            }

            backtrack(0, 0, 0)
            if (localBest > best) best = localBest
            return
        }

        for (valDot in 1..MAX_DOTS) {
            totalAssignments[v] = valDot
            dfsAssign(v + 1)
        }
    }

    dfsAssign(0)
    println(best)
}

