            genAssign(pos + 1, cur)
        }
    }
    genAssign(0, IntArray(n))

    // Precompute all domino types (a <= b)
    val dominoes = ArrayList<Pair<Int, Int>>()
    for (a in 1..MAX_DOTS) {
        for (b in a..MAX_DOTS) {
            dominoes.add(Pair(a, b))
        }
    }
