        for (i in 0 until m) {
            val newDp = dp.clone()
            val mask = edgeMask[i]
            if (mask != 0) {
                var sub = mask
                while (sub != 0) {
                    val d = sub and -sub
                    val idx = Integer.numberOfTrailingZeros(d)
                    val bit = 1 shl idx
                    var s = 0
                    while (s < maxState) {
                        if (dp[s] >= 0 && (s and bit) == 0) {
                            val ns = s or bit
                            if (newDp[ns] < dp[s] + 1) newDp[ns] = dp[s] + 1
                        }
                        s++
                    }
                    sub -= d
                }
            }
            for (s in 0 until maxState) {
                if (newDp[s] < dp[s]) newDp[s] = dp[s]
            }
            for (s in 0 until maxState) dp[s] = newDp[s]
        }

        for (v in dp) if (v > answer) answer = v
    }

    println(answer)
