    val dominoA = IntArray(21)
    val dominoB = IntArray(21)
    var idx = 0
    for (a in 1..MAX_DOTS) {
        for (b in a..MAX_DOTS) {
            dominoA[idx] = a
            dominoB[idx] = b
            idx++
        }
    }

    // Precompute all valid vertex labelings: each vertex gets label 0..6 (0 = no incoming)
    // For each labeling, we compute the best possible number of edges we can cover.
    val maxMask = IntArray(1 shl (3 * n)) { -1 } // not used directly, but to avoid huge memory we won't store all
    var answer = 0

    // Encode labeling as base-7 number: label[v] in [0..6]
    fun dfsLabel(pos: Int, code: Int, labels: IntArray) {
        if (pos == n) {
            // For this labeling, compute best number of edges
            val best = computeForLabeling(labels, edges, dominoA, dominoB)
            if (best > answer) answer = best
            return
        }
        for (lab in 0..MAX_DOTS) {
            labels[pos] = lab
            val newCode = code * 7 + lab
            dfsLabel(pos + 1, newCode, labels)
        }
    }

    dfsLabel(0, 0, IntArray(n))
    println(answer)
}

// For a fixed labeling, we need to choose a subset of edges and assign dominoes (types and orientation)
// respecting:
// - each domino type (a,b) used at most once
// - for each used edge (u,v), if labels[u]=x, labels[v]=y, then we must choose orientation and domino (a,b)
//   such that one side equals x (if x>0) and other equals y (if y>0); if label is 0, that endpoint imposes no constraint.
// We want to maximize number of edges used.
// This is a bipartite matching between edges and domino types with constraints.
private fun computeForLabeling(
    labels: IntArray,
    edges: List<Pair<Int, Int>>,
    dominoA: IntArray,
    dominoB: IntArray
): Int {
    val m = edges.size
    if (m == 0) return 0

    // Precompute for each edge, which domino indices can be used
    val edgeOptions = Array(m) { IntArray(0) }
    for (i in 0 until m) {
        val (u, v) = edges[i]
        val lu = labels[u]
        val lv = labels[v]
        val opts = ArrayList<Int>()
        for (d in 0 until 21) {
            val a = dominoA[d]
            val b = dominoB[d]
            if (canPlace(lu, lv, a, b)) {
                opts.add(d)
            }
        }
        if (opts.isEmpty()) {
            edgeOptions[i] = IntArray(0)
        } else {
            edgeOptions[i] = opts.toIntArray()
        }
    }

    // Simple backtracking: try to assign dominoes to edges
    val usedDomino = BooleanArray(21)
    var best = 0

    fun dfsEdge(pos: Int, usedCount: Int) {
        if (pos == m) {
            if (usedCount > best) best = usedCount
            return
        }
        // Upper bound pruning
        if (usedCount + (m - pos) <= best) return

        // Option 1: skip this edge
        dfsEdge(pos + 1, usedCount)

        // Option 2: try to use this edge with any available domino
        val opts = edgeOptions[pos]
        if (opts.isEmpty()) return
        for (d in opts) {
            if (!usedDomino[d]) {
                usedDomino[d] = true
                dfsEdge(pos + 1, usedCount + 1)
                usedDomino[d] = false
            }
        }
    }

    dfsEdge(0, 0)
    return best
}

// Check if we can place domino (a,b) on edge with labels lu, lv
// lu/lv in [0..6], 0 means no constraint
private fun canPlace(lu: Int, lv: Int, a: Int, b: Int): Boolean {
    // Try orientation 1: a->u, b->v
    if ((lu == 0 || lu == a) && (lv == 0 || lv == b)) return true
    // Try orientation 2: b->u, a->v
    if ((lu == 0 || lu == b) && (lv == 0 || lv == a)) return true
    return false
}

