private const val MAX_DOTS = 6
private const val DOMINO_TYPES = 21

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    val edges = ArrayList<Pair<Int, Int>>()
    repeat(m) {
        st = StringTokenizer(br.readLine())
        val a = st.nextToken().toInt() - 1
        val b = st.nextToken().toInt() - 1
        edges.add(Pair(a, b))
    }

    // Precompute all domino types (a,b) with 1<=a<=b<=6
    val domA = IntArray(DOMINO_TYPES)
    val domB = IntArray(DOMINO_TYPES)
    var idx = 0
    for (a in 1..MAX_DOTS) {
        for (b in a..MAX_DOTS) {
            domA[idx] = a
            domB[idx] = b
            idx++
        }
    }

    var best = 0

    // For each vertex, we will assign a value in [0..6], where 0 means "unused",
    // and 1..6 is the number of dots that must appear on all incident halves.
    val vertexDots = IntArray(n)

    // For each domino type, we can either not use it (state 0),
    // or use it in one of two orientations (state 1 or 2).
    // We'll iterate over all 3^21 possibilities using base-3 representation.
    val totalStates = Math.pow(3.0, DOMINO_TYPES.toDouble()).toLong()

    fun dfsDominoType(t: Int, usedCount: Int) {
        if (t == DOMINO_TYPES) {
            if (usedCount > best) best = usedCount
            return
        }

        // Pruning: even if we use all remaining dominoes, can't beat best
        if (usedCount + (DOMINO_TYPES - t) <= best) return

        val a = domA[t]
        val b = domB[t]

        // Option 0: don't use this domino
        dfsDominoType(t + 1, usedCount)

        // Try to place this domino on any edge in orientation (a->u, b->v)
        for ((u, v) in edges) {
            // orientation 1: u gets a, v gets b
            val oldU = vertexDots[u]
            val oldV = vertexDots[v]
            if ((oldU == 0 || oldU == a) && (oldV == 0 || oldV == b)) {
                vertexDots[u] = if (oldU == 0) a else oldU
                vertexDots[v] = if (oldV == 0) b else oldV
                dfsDominoType(t + 1, usedCount + 1)
                vertexDots[u] = oldU
                vertexDots[v] = oldV
            }

            // orientation 2: u gets b, v gets a (only if a!=b, otherwise same as orientation 1)
            if (a != b) {
                val oldU2 = vertexDots[u]
                val oldV2 = vertexDots[v]
                if ((oldU2 == 0 || oldU2 == b) && (oldV2 == 0 || oldV2 == a)) {
                    vertexDots[u] = if (oldU2 == 0) b else oldU2
                    vertexDots[v] = if (oldV2 == 0) a else oldV2
                    dfsDominoType(t + 1, usedCount + 1)
                    vertexDots[u] = oldU2
                    vertexDots[v] = oldV2
                }
            }
        }
    }

    dfsDominoType(0, 0)
    println(best)
}

