private const val MAX_DOTS = 6
private const val DOMINO_TYPES = 21

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    val edges = ArrayList<Pair<Int, Int>>()
    repeat(m) {
        st = StringTokenizer(br.readLine())
        val a = st.nextToken().toInt() - 1
        val b = st.nextToken().toInt() - 1
        edges.add(Pair(a, b))
    }

    // Precompute all domino types (a,b) with 1<=a<=b<=6
    val domA = IntArray(DOMINO_TYPES)
    val domB = IntArray(DOMINO_TYPES)
    var idx = 0
    for (a in 1..MAX_DOTS) {
        for (b in a..MAX_DOTS) {
            domA[idx] = a
            domB[idx] = b
            idx++
        }
    }

    val maxMask = 1 shl n
    var answer = 0

    // For each assignment of labels (1..6) to vertices (0..n-1)
    // represented as base-6 digits in an integer from 0 to 6^n - 1
    val totalAssignments = IntArray(n + 1)
    totalAssignments[0] = 1
    for (i in 1..n) totalAssignments[i] = totalAssignments[i - 1] * MAX_DOTS
    val limit = totalAssignments[n]

    val labels = IntArray(n)

    for (code in 0 until limit) {
        var tmp = code
        for (v in 0 until n) {
            labels[v] = (tmp % MAX_DOTS) + 1
            tmp /= MAX_DOTS
        }

        // For each edge, determine which domino type and orientation is required
        // and build adjacency between edges that conflict (share a domino type).
        val edgeDominoType = IntArray(m)
        val typeEdges = Array(DOMINO_TYPES) { ArrayList<Int>() }

        for (i in 0 until m) {
            val (u, v) = edges[i]
            val lu = labels[u]
            val lv = labels[v]
            val a = minOf(lu, lv)
            val b = maxOf(lu, lv)
            val t = dominoIndex(a, b)
            edgeDominoType[i] = t
            typeEdges[t].add(i)
        }

        // Build conflict graph: edges are vertices, conflict if same domino type
        val adj = IntArray(m)
        for (t in 0 until DOMINO_TYPES) {
            val list = typeEdges[t]
            val sz = list.size
            for (i in 0 until sz) {
                val ei = list[i]
                for (j in i + 1 until sz) {
                    val ej = list[j]
                    adj[ei] = adj[ei] or (1 shl ej)
                    adj[ej] = adj[ej] or (1 shl ei)
                }
            }
        }

        // Maximum independent set on graph with m <= 21
        val mis = maxIndependentSet(adj, m)
        if (mis > answer) answer = mis
    }

    println(answer)
}

private fun dominoIndex(a: Int, b: Int): Int {
    // Map (a,b) with 1<=a<=b<=6 to index 0..20
    var idx = 0
    var x = 1
    var y = 1
    while (true) {
        if (x == a && y == b) return idx
        y++
        if (y > MAX_DOTS) {
            x++
            y = x
        }
        idx++
    }
}

private fun maxIndependentSet(adj: IntArray, n: Int): Int {
    // Branch and bound for maximum independent set on up to 21 vertices
    val order = IntArray(n) { it }
    // Simple heuristic: sort by degree descending
    order.sortWith { i, j ->
        Integer.bitCount(adj[j]) - Integer.bitCount(adj[i])
    }

    fun dfs(pos: Int, current: Int, available: Int): Int {
        if (available == 0 || pos == n) return current
        // Upper bound: current + remaining vertices
        val remaining = Integer.bitCount(available)
        if (current + remaining <= best) return current
        var bestLocal = current
        var mask = available
        while (mask != 0) {
            val vBit = mask and -mask
            val v = Integer.numberOfTrailingZeros(vBit)
            val newAvailable = available and adj[v].inv() and ((1 shl n) - 1)
            val res = dfs(pos + 1, current + 1, newAvailable)
            if (res > bestLocal) bestLocal = res
            mask = mask xor vBit
        }
        return bestLocal
    }

    var initialMask = 0
    for (i in 0 until n) initialMask = initialMask or (1 shl i)
    best = 0
    best = dfs(0, 0, initialMask)
    return best
}

private var best = 0

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MAX_DOTS = 6
private const val MAX_VERTICES = 7

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    val edges = ArrayList<Pair<Int, Int>>(m)
    repeat(m) {
        st = StringTokenizer(reader.readLine())
        val a = st.nextToken().toInt() - 1
        val b = st.nextToken().toInt() - 1
        edges.add(Pair(a, b))
    }

    val totalDominoes = 21
    val dominoA = IntArray(totalDominoes)
    val dominoB = IntArray(totalDominoes)
    var idx = 0
    for (a in 1..MAX_DOTS) {
        for (b in a..MAX_DOTS) {
            dominoA[idx] = a
            dominoB[idx] = b
            idx++
        }
    }

    val usedDomino = BooleanArray(totalDominoes)
    val vertexLabel = IntArray(n) { 0 } // 0 means unlabeled
    var best = 0

    fun dfs(edgeIndex: Int, placed: Int) {
        if (placed + (m - edgeIndex) <= best) return
        if (edgeIndex == m) {
            if (placed > best) best = placed
            return
        }

        val (u, v) = edges[edgeIndex]
        val lu = vertexLabel[u]
        val lv = vertexLabel[v]

        // Option 1: skip this edge
        dfs(edgeIndex + 1, placed)

        // Option 2: try to place a domino
        for (d in 0 until totalDominoes) {
            if (usedDomino[d]) continue
            val a = dominoA[d]
            val b = dominoB[d]

            // Try orientation u<-a, v<-b
            fun tryOrientation(au: Int, av: Int) {
                val oldLu = lu
                val oldLv = lv
                var ok = true

                if (oldLu == 0) {
                    vertexLabel[u] = au
                } else if (oldLu != au) {
                    ok = false
                }

                if (ok) {
                    if (oldLv == 0) {
                        vertexLabel[v] = av
                    } else if (oldLv != av) {
                        ok = false
                    }
                }

                if (ok) {
                    usedDomino[d] = true
                    dfs(edgeIndex + 1, placed + 1)
                    usedDomino[d] = false
                }

                vertexLabel[u] = oldLu
                vertexLabel[v] = oldLv
            }

            // orientation 1: u<-a, v<-b
            tryOrientation(a, b)
            if (a != b) {
                // orientation 2: u<-b, v<-a
                tryOrientation(b, a)
            }
        }
    }

    dfs(0, 0)
    println(best)
}
